package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.clients.Currency;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

/**
 * The workspace's exchange rates: the US dollars one unit of each currency is worth, stored as the
 * {@code usd_per_<code>} settings. A US dollar is worth one; a currency with no rate set is taken
 * at par. Dated rates (the {@code fx_rate} table) take over from their date on: something converted on
 * a date uses the latest dated rate on or before it, or the standing rate before any. Invoices read
 * their client's rates themselves (see Invoice).
 */
@Service
public class ExchangeRates {

    /** The prefix of the setting holding a currency's rate, followed by its code (usd_per_EUR). */
    public static final String USD_PER = "usd_per_";

    private final JdbcTemplate jdbc;

    public ExchangeRates(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every rate set, by currency code. */
    public Map<String, BigDecimal> all() {
        Map<String, BigDecimal> rates = new LinkedHashMap<>();
        jdbc.queryForList("SELECT name, setting_value FROM app_setting WHERE name LIKE ? ORDER BY name", USD_PER + "%")
                .forEach(r -> rates.put(((String) r.get("NAME")).substring(USD_PER.length()),
                        new BigDecimal((String) r.get("SETTING_VALUE"))));
        return rates;
    }

    /** A dated rate: from the date on, the US dollars one unit of the currency is worth. */
    public record Dated(LocalDate from, Currency currency, BigDecimal usdPer) {
    }

    /** Every dated rate, by date then currency. */
    public List<Dated> dated() {
        return jdbc.query("SELECT from_date, currency, usd_per FROM fx_rate ORDER BY from_date, currency, id",
                (rs, n) -> new Dated(rs.getDate(1).toLocalDate(), Currency.of(rs.getString(2)), rs.getBigDecimal(3)));
    }

    /** Adds a dated rate. */
    public void addDated(LocalDate from, Currency currency, BigDecimal usdPer) {
        jdbc.update("INSERT INTO fx_rate (from_date, currency, usd_per) VALUES (?, ?, ?)", Date.valueOf(from),
                currency.name(), usdPer);
    }

    /**
     * The US dollars one unit of the currency is worth on the date: the latest dated rate on or before
     * it, otherwise the standing rate (see {@link #usdPer(Currency)}).
     */
    public BigDecimal usdPer(Currency currency, LocalDate on) {
        if (currency == Currency.USD) {
            return BigDecimal.ONE;
        }
        return jdbc.queryForList("SELECT usd_per FROM fx_rate WHERE currency = ? AND from_date <= ? ORDER BY from_date DESC, id DESC LIMIT 1",
                BigDecimal.class, currency.name(), Date.valueOf(on)).stream().findFirst().orElseGet(() -> usdPer(currency));
    }

    /** The US dollars one unit of the currency is worth: one for the dollar or a currency with no rate set. */
    public BigDecimal usdPer(Currency currency) {
        if (currency == Currency.USD) {
            return BigDecimal.ONE;
        }
        return jdbc.queryForList("SELECT setting_value FROM app_setting WHERE name = ?", String.class, USD_PER + currency.name())
                .stream().findFirst().map(v -> new BigDecimal(v.trim())).orElse(BigDecimal.ONE);
    }

    /**
     * The amount paid in one currency converted into another through US dollars: amount x (dollars per
     * unit paid) / (dollars per unit of the other), at the rates in force on the date, worked out exactly
     * and rounded down to the other's step, so the client is never credited more than was received.
     */
    public BigDecimal convert(BigDecimal amount, Currency from, Currency to, LocalDate on) {
        if (from == to) {
            return amount.setScale(to.scale());
        }
        return to.divideDownToStep(amount.multiply(usdPer(from, on)), usdPer(to, on));
    }
}
package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.math.MathContext;
import java.math.RoundingMode;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

/**
 * The workspace's card surcharge: the stored {@code card_surcharge_pct} setting, a percentage such as
 * 2.5 passed on to a client paying by card; 0 when none is set. Part of a card payment is the
 * surcharge: the amount less the amount divided by 1 plus the rate, rounded half up to the cent.
 */
@Service
public class CardSurcharge {

    public static final String CARD_SURCHARGE_PCT = "card_surcharge_pct";

    private final JdbcTemplate jdbc;

    public CardSurcharge(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public BigDecimal percent() {
        List<String> rate = jdbc.queryForList("SELECT setting_value FROM app_setting WHERE name = ?",
                String.class, CARD_SURCHARGE_PCT);
        return rate.isEmpty() ? BigDecimal.ZERO : new BigDecimal(rate.get(0));
    }

    /** The surcharge in the amount paid by card, rounded half up to the scale (2 for cents, 0 for yen). */
    public BigDecimal of(BigDecimal amount, int scale) {
        BigDecimal rate = percent();
        if (rate.signum() == 0) {
            return BigDecimal.ZERO.setScale(scale);
        }
        BigDecimal factor = BigDecimal.ONE.add(rate.movePointLeft(2));
        BigDecimal net = amount.divide(factor, MathContext.DECIMAL128);
        return amount.subtract(net).setScale(scale, RoundingMode.HALF_UP);
    }
}
package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.clients.Currency;
import net.officefloor.hq.app.clients.RateTiers;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

/**
 * The workspace price list (the {@code price_list_rate} table): a price in US dollars per unit type,
 * a single price or tiers (see {@link RateTiers}), for unit types a client's own rate card doesn't
 * cover. A line priced from it gets each price, or each band's price, converted into the client's
 * currency at the rates on the invoice's issue date, rounded down to the currency's step.
 */
@Service
public class PriceList {

    private final JdbcTemplate jdbc;
    private final ExchangeRates exchangeRates;

    public PriceList(JdbcTemplate jdbc, ExchangeRates exchangeRates) {
        this.jdbc = jdbc;
        this.exchangeRates = exchangeRates;
    }

    /** An entry of the price list: its unit type and a single unit price or tiers, in US dollars. */
    public record Entry(String unitType, BigDecimal unitPrice, RateTiers tiers) {
    }

    /** A price converted into a client's currency: a single unit price, or tiers in their stored form. */
    public record Converted(BigDecimal unitPrice, String tiers) {
    }

    /** Every entry, by unit type. */
    public List<Entry> all() {
        return jdbc.query("SELECT unit_type, unit_price, tiers FROM price_list_rate ORDER BY unit_type",
                (rs, n) -> new Entry(rs.getString(1), rs.getBigDecimal(2), RateTiers.parse(rs.getString(3))));
    }

    /** Adds an entry: a single unit price, or tiers. */
    public void add(String unitType, BigDecimal unitPrice, RateTiers tiers) {
        jdbc.update("INSERT INTO price_list_rate (unit_type, unit_price, tiers) VALUES (?, ?, ?)", unitType,
                tiers == null ? unitPrice : null, tiers == null ? null : tiers.format());
    }

    /**
     * The price list's price for the unit type (matched ignoring case) converted into the currency at
     * the rates on the date, or null when the price list has none.
     */
    public Converted priceFor(String unitType, Currency currency, LocalDate on) {
        List<Map<String, Object>> found = jdbc.queryForList(
                "SELECT unit_price, tiers FROM price_list_rate WHERE LOWER(unit_type) = LOWER(?)", unitType.trim());
        if (found.isEmpty()) {
            return null;
        }
        RateTiers tiers = RateTiers.parse((String) found.get(0).get("TIERS"));
        if (tiers != null) {
            RateTiers converted = new RateTiers(tiers.bands().stream()
                    .map(b -> new RateTiers.Band(b.units(), convert(b.unitPrice(), currency, on))).toList());
            return new Converted(converted.firstPrice(), converted.format());
        }
        return new Converted(convert((BigDecimal) found.get(0).get("UNIT_PRICE"), currency, on), null);
    }

    private BigDecimal convert(BigDecimal usd, Currency currency, LocalDate on) {
        return exchangeRates.convert(usd, Currency.USD, currency, on);
    }
}
